'use strict';
const modules = [...(window.GPU_FOUNDATIONS || []), ...(window.GPU_PERFORMANCE || []), ...(window.GPU_PRODUCTION || [])];
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = x => String(x ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key = 'gpu-field-guide-progress-v1';
let completed = new Set();
try { const saved = JSON.parse(localStorage.getItem(key) || '[]'); if (Array.isArray(saved)) completed = new Set(saved.filter(id => modules.some(m => m.id === id))); } catch (_) {}
let activeGroup = 'All', filterText = '', activeTool = 'memory';
const groups = ['Foundations', 'Performance', 'Production'];
const groupInfo = [
  ['The machine underneath','Understand how GPUs execute work, move data, and turn tensors into parallel computation.','▦','7 modules · Build your foundation'],
  ['From working to fast','Read a profile. Find the bottleneck. Make training and inference faster with evidence.','⌁','7 modules · Measure & optimize'],
  ['From one GPU to a system','Deploy, observe, and operate reliable GPU workloads. Connect the single device to the wider stack.','⤧','6 modules · Think in systems']
];
function toast(message) { $('#toast').textContent = message; $('#toast').classList.add('show'); clearTimeout(toast.timer); toast.timer = setTimeout(() => $('#toast').classList.remove('show'), 2500); }
function updateProgress() { $('#progress-count').textContent = `${completed.size} / ${modules.length}`; $('#progress-bar').style.width = `${completed.size / Math.max(1, modules.length) * 100}%`; }
function saveProgress() { try { localStorage.setItem(key, JSON.stringify([...completed])); } catch (_) { toast('Progress is available for this visit; browser storage is unavailable.'); } updateProgress(); }
function chipIllustration() {
 const tiles = Array.from({length:16}, (_,i) => { const x=159+(i%4)*28,y=137+Math.floor(i/4)*24; return `<rect x="${x}" y="${y}" width="22" height="18" rx="2" fill="${i%3===0?'#cce3a2':'#a9c580'}"/><path d="M${x+5} ${y+5}h12m-12 4h12m-12 4h7" stroke="#537748" stroke-width="1.5" opacity=".7"/>`; }).join('');
 return `<div class="chip-scene"><svg viewBox="0 0 440 350" role="img" aria-label="Conceptual GPU schematic showing compute units, cache and device memory, not a specific chip layout"><defs><pattern id="grid" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M20 0H0V20" fill="none" stroke="#ced9c0" stroke-width=".5"/></pattern><filter id="shadow"><feDropShadow dx="0" dy="9" stdDeviation="8" flood-color="#557347" flood-opacity=".15"/></filter></defs><rect width="440" height="350" fill="url(#grid)"/><g stroke="#b1c29c" fill="none" stroke-width="1.1"><path d="M65 112h50l28 28m-91 42h90m-70 65h44l28-28M295 140l28-28h59m-85 70h95m-95 33 30 30h49M180 78v32m40-52v50m40-30v32M180 245v31m40-29v46m40-46v31"/><circle cx="65" cy="112" r="3"/><circle cx="52" cy="182" r="3"/><circle cx="382" cy="112" r="3"/><circle cx="392" cy="182" r="3"/></g><g filter="url(#shadow)"><rect x="116" y="104" width="208" height="152" rx="10" fill="#bccca5"/><rect x="125" y="96" width="190" height="151" rx="8" fill="#234c41" stroke="#426a4f" stroke-width="2"/><rect x="145" y="119" width="150" height="115" rx="4" fill="#466d4b" stroke="#9cb77e"/>${tiles}<path d="M150 111h140M150 240h140" stroke="#96b277" stroke-width="4"/></g><g fill="#91aa70" stroke="#e1e8d5" stroke-width="1"><rect x="80" y="136" width="32" height="31" rx="3"/><rect x="80" y="190" width="32" height="31" rx="3"/><rect x="328" y="136" width="32" height="31" rx="3"/><rect x="328" y="190" width="32" height="31" rx="3"/></g><g fill="#607b51" font-family="monospace" font-size="8" letter-spacing="1"><text x="26" y="37">FIG. 01 — INSIDE THE GPU</text><text x="26" y="315">PARALLEL BY DESIGN</text><text x="329" y="315">NOT TO SCALE</text><text x="240" y="55">COMPUTE</text><text x="34" y="89">DEVICE MEMORY</text><text x="332" y="274">CACHE</text></g><g stroke="#6e8c55" stroke-width=".8" fill="none"><path d="M260 61v24l-15 12M70 94v35l13 8M332 262h-28l-18-23"/></g><g fill="#d7663d"><circle cx="245" cy="97" r="2.5"/><circle cx="83" cy="137" r="2.5"/><circle cx="286" cy="239" r="2.5"/></g><rect x="329" y="25" width="85" height="19" rx="3" fill="#dae6c7" stroke="#bacba5"/><text x="340" y="37" font-family="monospace" font-size="8" fill="#557440">SINGLE DEVICE</text></svg><div class="diagram-caption"><span><i></i> MANY CORES. ONE MENTAL MODEL.</span><span>EXPLORE ↓</span></div></div>`;
}
function lessonRow(m) { const n = modules.indexOf(m)+1; return `<a class="lesson-row" href="#lesson/${esc(m.id)}"><span class="lesson-number ${completed.has(m.id)?'done-dot':''}">${completed.has(m.id)?'✓':String(n).padStart(2,'0')}</span><div><h3>${esc(m.title)}</h3><p>${esc(m.summary)}</p></div><div class="lesson-meta"><span>${esc(m.level)}</span>${m.minutes} MIN + LAB</div><span class="lesson-arrow">↗</span></a>`; }
function intro(tag,title,text) { return `<div class="page-intro"><span class="eyebrow">${tag}</span><h1>${title}</h1><p>${text}</p></div>`; }
function overview() {
 const next = modules.find(m => !completed.has(m.id)) || modules[0];
 return `<section class="hero"><div><div class="eyebrow">THE AI INFRASTRUCTURE HANDBOOK</div><h1>Understand the GPU.<br><em>Build the<br>infrastructure.</em></h1><p>From the first warp to your first production workload. A practical field guide to the hardware, software, and systems behind AI.</p><div class="hero-actions"><a class="button" href="#lesson/${next?.id || 'compute-model'}">${completed.size?'Continue learning':'Start the learning path'} <span>↗</span></a><a class="button light" href="#playground">Explore the playground</a></div><div class="hero-note"><span>NVIDIA / CUDA FIRST</span><span>CONCEPTS → LABS → SYSTEMS</span></div></div>${chipIllustration()}</section><section class="stats-bar" aria-label="Guide contents"><div class="stat"><strong>${modules.length}</strong><span>Deep-dive modules</span></div><div class="stat"><strong>3</strong><span>Learning stages</span></div><div class="stat"><strong>20</strong><span>Hands-on checkpoints</span></div><div class="stat"><strong>8 weeks</strong><span>A suggested pace, yours to adapt</span></div></section><section><div class="section-head"><div><span class="eyebrow">A PATH THROUGH THE STACK</span><h2>One GPU. A world to understand.</h2></div><a href="#curriculum">View full curriculum ↗</a></div><div class="tracks">${groups.map((g,i)=>`<a class="track" href="#curriculum/${g}"><div class="track-top"><span class="number">0${i+1} / ${g.toUpperCase()}</span><span class="track-icon">${groupInfo[i][2]}</span></div><h3>${groupInfo[i][0]}</h3><p>${groupInfo[i][1]}</p><div class="track-bottom"><span>${groupInfo[i][3]}</span><span>↗</span></div></a>`).join('')}</div></section><section class="feature-strip"><span class="feature-icon">⌘</span><div><h3>Build intuition before you rent a GPU.</h3><p>Estimate model memory, explore the roofline, and trace the path of your data.</p></div><a class="button light" href="#playground">Open playground <span>↗</span></a></section><section><div class="section-head"><div><span class="eyebrow">BEGIN WITH THE FUNDAMENTALS</span><h2>Your first three field notes.</h2></div><a href="#curriculum">All 20 modules ↗</a></div>${modules.slice(0,3).map(lessonRow).join('')}</section><p class="notice" style="margin-top:30px">Start with basic Python, Linux command-line skills, and matrix multiplication. The browser tools need no GPU. CUDA and PyTorch labs require a suitable NVIDIA GPU and a compatible environment. This is a broad, practical foundation; hardware generations and engineering specializations require further study.</p>`;
}
function curriculum(group='All') { activeGroup = groups.includes(group)?group:'All'; filterText=''; return `${intro('01—03 / THE COMPLETE LEARNING PATH','Learn the stack, layer by layer.','Twenty focused modules connect a single GPU to the responsibilities of an AI infrastructure engineer. Read the concepts, run a small experiment, and explain what you measured.')}<div class="filterbar" role="group" aria-label="Filter curriculum">${['All',...groups].map(g=>`<button class="pill ${g===activeGroup?'active':''}" data-group="${g}">${g==='All'?'All modules':g}</button>`).join('')}<label class="sr-only" for="curriculum-search">Filter lessons</label><input id="curriculum-search" type="search" placeholder="Filter topics, tools, concepts…"></div><div id="module-list">${moduleList()}</div>`; }
function matches(m,q){return `${m.title} ${m.summary} ${m.tags.join(' ')} ${m.sections.map(s=>s.heading+' '+s.body).join(' ')}`.toLowerCase().includes(q.toLowerCase());}
function moduleList() { const list=modules.filter(m=>(activeGroup==='All'||m.group===activeGroup)&&matches(m,filterText)); return list.length?groups.map(g=>{const ms=list.filter(m=>m.group===g);return ms.length?`<section class="module-group"><div class="group-label">${g} <span>${ms.length} modules</span></div>${ms.map(lessonRow).join('')}</section>`:'';}).join(''):'<p class="empty">No matching lessons. Try a broader term such as memory or CUDA.</p>'; }
function lesson(id) {
 const m=modules.find(m=>m.id===id); if(!m)return `${intro('TOPIC NOT FOUND','Let’s return to the map.','This lesson address is not part of the guide.')}<a class="button" href="#curriculum">Browse the curriculum ↗</a>`;
 const index=modules.indexOf(m); const next=modules[index+1];
 return `<div class="lesson-top"><a href="#curriculum">← Learning path</a><span>/</span><span>${esc(m.group)}</span><span>/</span><span>MODULE ${String(index+1).padStart(2,'0')}</span><span>· ${m.minutes} min reading + lab</span></div><h1 class="lesson-title">${esc(m.title)}</h1><p class="lesson-summary">${esc(m.summary)}</p><div>${m.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="lesson-layout"><article class="lesson-content"><div class="objective-box"><h2>By the end of this module</h2><ul>${m.objectives.map(o=>`<li>${esc(o)}</li>`).join('')}</ul></div>${m.sections.map((s,i)=>`<section class="reading-section" id="section-${i}"><h2>${esc(s.heading)}</h2><p>${esc(s.body)}</p></section>`).join('')}<section class="lab-box" id="lab"><span class="eyebrow">FIELD EXERCISE / APPLY THE CONCEPT</span><h2>${esc(m.lab.title)}</h2><ol>${m.lab.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="code-wrap"><div class="code-label"><span>LAB NOTES & CODE · REVIEW BEFORE RUNNING</span><button class="copy-code" data-copy="${m.id}">Copy</button></div><pre><code>${esc(m.lab.code)}</code></pre></div><p class="success"><strong>Checkpoint →</strong> ${esc(m.lab.success)}</p></section><section class="quiz" id="checkpoint"><span class="eyebrow">CHECK YOUR MENTAL MODEL</span><h2>${esc(m.quiz.question)}</h2><div class="choices">${m.quiz.choices.map((c,i)=>`<button class="choice" data-answer="${i}" data-lesson="${m.id}">${String.fromCharCode(65+i)}. ${esc(c)}</button>`).join('')}</div><p class="quiz-result" role="status"></p></section><section class="lesson-source" id="sources"><h2>Go to the source</h2><p style="font-size:12px">Primary references for deeper study. APIs and hardware support vary by version.</p>${m.sources.map(s=>`<a target="_blank" rel="noopener noreferrer" href="${esc(s.url)}">${esc(s.label)} ↗</a>`).join('')}</section><div class="lesson-end"><button class="button ${completed.has(id)?'light':''}" data-complete="${id}">${completed.has(id)?'✓ Completed · mark unread':'Mark module complete ✓'}</button>${next?`<a class="button light" href="#lesson/${next.id}">Next module →</a>`:'<a class="button light" href="#interview">Build your portfolio →</a>'}</div></article><aside class="lesson-toc"><span class="eyebrow">IN THIS FIELD NOTE</span>${m.sections.map((s,i)=>`<a href="#section-${i}" data-scroll="section-${i}">${esc(s.heading)}</a>`).join('')}<a href="#lab" data-scroll="lab">↗ Field exercise</a><a href="#checkpoint" data-scroll="checkpoint">◎ Knowledge check</a><a href="#sources" data-scroll="sources">Primary references</a></aside></div>`;
}
function field(id,label,value,help='',step='1',min='0') {return `<div class="field"><label for="${id}">${label}</label><input id="${id}" type="number" min="${min}" step="any" value="${value}">${help?`<small>${help}</small>`:''}</div>`;}
function playground(){return `${intro('THE GPU PLAYGROUND','Make the invisible tangible.','Change a workload. See what moves. These conceptual models build intuition before profiling a real device; they are estimates, not hardware benchmarks.')}<div class="filterbar play-tabs" role="group" aria-label="Playground tool"><button class="pill ${activeTool==='memory'?'active':''}" data-tool="memory">01 · Memory budget</button><button class="pill ${activeTool==='roofline'?'active':''}" data-tool="roofline">02 · Roofline explorer</button><button class="pill ${activeTool==='architecture'?'active':''}" data-tool="architecture">03 · Inside the GPU</button></div><div id="tool-content">${toolContent()}</div>`;}
function toolContent(){
 if(activeTool==='roofline')return `<section class="tool-panel"><div class="tool-heading"><h2>What limits this kernel?</h2><p>A two-ceiling roofline for a hypothetical GPU. Use dense compute and bandwidth figures with consistent precision.</p></div><div class="tool-grid"><div class="tool-inputs">${field('peak','Peak compute · TFLOP/s',100,'Illustrative, not a device specification',1,.01)}${field('bandwidth','Memory bandwidth · GB/s',1000,'Decimal GB/s; choose the relevant memory level',1,.01)}${field('intensity','Arithmetic intensity · FLOP/byte',20,'FLOPs per byte transferred at that level',1,.001)}</div><div class="tool-output"><span class="eyebrow">IDEAL UPPER BOUND</span><div class="big-number" id="roof-value"></div><p id="roof-bound"></p><div class="breakdown" id="roof-detail"></div><div class="formula">attainable TFLOP/s ≤ min(peak, bandwidth × intensity / 1000)</div></div></div><div class="roof-chart" id="roof-chart"></div><div class="tool-note">The ridge point is peak FLOP/s ÷ bandwidth in bytes/s. Real kernels sit below the ceiling because of occupancy, instruction mix, launch overhead, latency, and other constraints. Tensor Core and scalar paths have different compute ceilings; sparse peak numbers are not dense throughput. <a href="#lesson/roofline"><u>Read the roofline module →</u></a></div></section>`;
 if(activeTool==='architecture')return `<section class="tool-panel"><div class="tool-heading"><h2>Follow the work through a GPU.</h2><p>Select a component to connect hardware structure to a performance decision. This is a conceptual NVIDIA-style model.</p></div><div class="arch-grid"><div class="arch-diagram" role="group" aria-label="GPU components"><button data-part="host">CPU / HOST MEMORY ↔ PCIe</button><button data-part="vram">DEVICE MEMORY · HBM / GDDR</button><button data-part="cache">SHARED L2 CACHE</button><div class="arch-sm"><button data-part="sm" class="active">SM · SCHEDULERS</button><button data-part="tensor">TENSOR CORES</button><button data-part="shared">SHARED MEMORY / L1</button><button data-part="registers">REGISTERS</button></div></div><div class="arch-desc" id="arch-desc"></div></div><div class="tool-note">SM counts, cache sizes, shared-memory relationships, Tensor Core features, and copy capabilities vary across GPU generations. The drawing shows conceptual roles, not physical placement or a universal latency table. <a href="#lesson/gpu-architecture"><u>Read the architecture module →</u></a></div></section>`;
 return `<section class="tool-panel"><div class="tool-heading"><h2>Will the workload fit?</h2><p>Explore model weights, KV cache, and training state. All outputs use GiB (2³⁰ bytes); parameter counts use decimal billions.</p></div><div class="tool-grid"><div class="tool-inputs"><div class="field"><label for="mode">Workload</label><select id="mode"><option value="inference">LLM inference</option><option value="training">Full fine-tuning · Adam</option></select></div>${field('params','Parameters · billions',7,'Total parameter count',.1,.01)}<div class="field"><label for="weight-bytes">Weight storage</label><select id="weight-bytes"><option value="2">BF16 / FP16 · 2 bytes</option><option value="4">FP32 · 4 bytes</option><option value="1">INT8 · 1 byte (ideal)</option><option value="0.5">INT4 · 0.5 bytes (ideal)</option></select></div>${field('capacity','Available VRAM · GiB',24,'Budget on the chosen GPU',1,.1)}<div class="field infer-field"><label for="kv-bytes">KV-cache dtype</label><select id="kv-bytes"><option value="2">BF16 / FP16 · 2 bytes</option><option value="1">8-bit · 1 byte (ideal)</option><option value="4">FP32 · 4 bytes</option></select></div>${field('reserve','Runtime reserve · GiB',2,'Workspace, allocator, temporary buffers',.5,0)}<div class="field infer-field"><label for="tokens">Tokens per sequence</label><input id="tokens" type="number" min="1" step="1" value="4096"><small>Prompt + generated tokens retained</small></div><div class="field infer-field"><label for="batch">Concurrent sequences</label><input id="batch" type="number" min="1" step="1" value="1"></div><div class="field infer-field"><label for="layers">Transformer layers</label><input id="layers" type="number" min="1" step="1" value="32"></div><div class="field infer-field"><label for="kv-heads">KV heads per layer</label><input id="kv-heads" type="number" min="1" step="1" value="8"><small>KV heads, not query heads (GQA)</small></div><div class="field infer-field"><label for="head-dim">Head dimension</label><input id="head-dim" type="number" min="1" step="1" value="128"></div><div class="field train-field" hidden><label for="activations">Activations · GiB</label><input id="activations" type="number" min="0" step=".5" value="8"><small>Workload-dependent; supply a measured estimate</small></div></div><div class="tool-output"><span class="eyebrow">ESTIMATED MEMORY</span><div class="big-number" id="memory-total"></div><p id="fit-result" role="status"></p><div class="memory-bar" id="memory-bar" aria-hidden="true"></div><div class="breakdown" id="memory-detail"></div><div class="formula" id="memory-formula"></div></div></div><div class="tool-note" id="memory-note"></div></section>`;
}
const archParts={
 host:['The host starts the work.','The CPU runs application logic, launches kernels, and schedules transfers. Data commonly crosses PCIe before GPU execution; reducing repeated transfers can matter more than optimizing a kernel.',['Pinned host memory can enable asynchronous DMA.','Overlap needs suitable streams, hardware support, and independent work.','Measure end-to-end latency alongside GPU-only time.']],
 vram:['Capacity and bandwidth are different constraints.','Device memory holds weights, activations, KV cache, and temporary buffers. HBM and GDDR describe memory technologies; the exact capacity and bandwidth depend on the device.',['An out-of-memory error is a capacity problem.','Low arithmetic intensity may make throughput bandwidth-bound.','Coalescing and reuse reduce avoidable memory traffic.']],
 cache:['Reuse data before it leaves the chip.','L2 is a device-wide cache shared by SMs on the conceptual model. A cache hit avoids a trip to device memory, so the relevant bandwidth ceiling depends on which memory level supplies the data.',['Do not treat every load as an HBM transaction.','Working-set size and access pattern affect cache hit rate.','Repeated microbenchmarks can warm caches unrealistically.']],
 sm:['The streaming multiprocessor does the work.','An SM schedules warps onto its execution resources. On CUDA GPUs a warp contains 32 threads. Resident warps help hide latency while other warps wait for data or dependencies.',['Registers, shared memory, and block size limit residency.','Higher occupancy does not guarantee higher performance.','Divergent paths can reduce useful work within a warp.']],
 tensor:['Matrix math has specialized hardware.','Tensor Cores accelerate supported matrix operations and datatypes. They are execution units inside the GPU, not extra general-purpose GPUs. Efficient use depends on kernel choice, shape, layout, and precision.',['Peak throughput is datatype- and operation-specific.','Small or awkward matrix shapes may underuse the hardware.','Validate numerical quality after changing precision.']],
 shared:['Cooperate within a thread block.','Shared memory is explicitly managed on-chip storage that threads in a block can use for reuse and communication. On many NVIDIA architectures its capacity is related to L1 resources; details vary.',['Tiled matrix multiplication reuses loaded tiles.','Bank conflicts can serialize accesses.','Synchronize participating threads correctly before reuse.']],
 registers:['Fast private state comes with a budget.','Registers hold per-thread values. Heavy register demand can reduce the number of resident warps; spilling can send thread-local data to memory backed by device DRAM.',['Large temporary arrays can create register pressure.','Local memory describes scope, not necessarily on-chip storage.','Inspect compiler and profiler evidence before tuning.']]
};
function updateArchitecture(part='sm'){const [h,p,ls]=archParts[part];$('#arch-desc').innerHTML=`<span class="eyebrow">INSIDE THE DEVICE / ${part.toUpperCase()}</span><h3>${h}</h3><p>${p}</p><ul>${ls.map(x=>`<li>${x}</li>`).join('')}</ul>`;}
function numeric(id){const el=$('#'+id),v=Number(el.value);return el.value.trim()!==''&&Number.isFinite(v)&&v>=Number(el.min||0)&&el.validity.valid?v:NaN;}
function memoryBudget(v){const GiB=2**30,weights=v.params*1e9*v.weightBytes/GiB;const kv=2*v.layers*v.batch*v.tokens*v.kvHeads*v.headDim*v.kvBytes/GiB;const state=v.params*1e9*16/GiB;const extra=v.mode==='training'?state+v.activations:kv;return {weights,kv,state,extra,total:weights+extra+v.reserve};}
function updateMemory(){
 const mode=$('#mode').value,training=mode==='training';$$('.infer-field').forEach(e=>e.hidden=training);$$('.train-field').forEach(e=>e.hidden=!training);$('#weight-bytes').disabled=training;if(training)$('#weight-bytes').value='2';
 const v={mode,params:numeric('params'),weightBytes:Number($('#weight-bytes').value),capacity:numeric('capacity'),reserve:numeric('reserve'),tokens:numeric('tokens'),batch:numeric('batch'),layers:numeric('layers'),kvHeads:numeric('kv-heads'),headDim:numeric('head-dim'),kvBytes:Number($('#kv-bytes').value),activations:numeric('activations')};
 const required=training?[v.params,v.capacity,v.reserve,v.activations]:[v.params,v.capacity,v.reserve,v.tokens,v.batch,v.layers,v.kvHeads,v.headDim];
 if(required.some(x=>!Number.isFinite(x))){$('#memory-total').textContent='—';$('#fit-result').textContent='Enter valid, non-negative values; dimensions must be positive integers.';$('#memory-detail').innerHTML='';$('#memory-bar').innerHTML='';$('#memory-formula').textContent='';return;}
 const b=memoryBudget(v),fmt=x=>x.toFixed(2)+' GiB';if(!Number.isFinite(b.total)){ $('#memory-total').textContent='—';$('#fit-result').textContent='Values exceed the calculator range. Use realistic workload dimensions.';$('#memory-detail').innerHTML='';$('#memory-bar').innerHTML='';$('#memory-formula').textContent='';return;}$('#memory-total').innerHTML=`${b.total.toFixed(2)} <small>GiB</small>`;const remaining=v.capacity-b.total;$('#fit-result').textContent=remaining>=0?`${remaining.toFixed(2)} GiB of modeled headroom. Validate against a real peak-memory measurement.`:`${(-remaining).toFixed(2)} GiB over this budget. Reduce workload memory or use a larger device.`;$('#fit-result').style.color=remaining<0?'#b95534':'#536d3f';
 const items=training?[['Weights · BF16 / FP16',b.weights],['FP32 master weights + gradients + Adam moments',b.state],['Activations · supplied estimate',v.activations],['Runtime reserve',v.reserve]]:[['Model weights',b.weights],['KV cache',b.kv],['Runtime reserve',v.reserve]];
 $('#memory-detail').innerHTML=items.map(([label,n])=>`<div><span>${label}</span><strong>${fmt(n)}</strong></div>`).join('')+`<div><span>Available VRAM</span><strong>${fmt(v.capacity)}</strong></div>`;
 $('#memory-bar').innerHTML=items.map(([,n],i)=>`<span style="width:${n/Math.max(b.total,v.capacity)*100}%;background:${['#355849','#9bb76e','#d2b98b','#aab5a2'][i]}"></span>`).join('');
 $('#memory-formula').textContent=training?'State = P × (2B weights + 4B master + 4B gradients + 8B moments)\nTotal = state + activations + reserve':'Weights = P × weight bytes\nKV = 2 × layers × sequences × tokens × KV heads × head dimension × cache bytes\nTotal = weights + KV + reserve';
 $('#memory-note').textContent=training?'Training model: an illustrative mixed-precision Adam implementation uses 18 bytes/parameter including FP32 master weights, FP32 gradients, and two FP32 moments. Actual optimizers, gradient dtype, sharding, LoRA, and checkpointing change this substantially. Activation memory is supplied separately, not predicted from parameter count.':'Inference model: dense decoder-only transformer with uniform full-attention layers, all tokens retained, equal sequence lengths, and no cache sharing. Quantized sizes omit scales, zero points, and padding. Runtime reserve is a user-supplied allowance; activations and workspace can exceed it. Sliding windows, MLA, cache eviction, and serving implementation change the result.';
}
function roofline(p,b,a){return {ridge:p*1000/b,memory:b*a/1000,attainable:Math.min(p,b*a/1000)};}
function updateRoofline(){const p=numeric('peak'),b=numeric('bandwidth'),a=numeric('intensity');if([p,b,a].some(v=>!Number.isFinite(v)||v<=0)){$('#roof-value').textContent='—';$('#roof-bound').textContent='Enter positive values.';$('#roof-detail').innerHTML='';$('#roof-chart').innerHTML='';return;}const r=roofline(p,b,a);if(![r.ridge,r.memory,r.attainable,r.ridge*2,a*1.2].every(Number.isFinite)){ $('#roof-value').textContent='—';$('#roof-bound').textContent='Values exceed the calculator range. Use realistic device figures.';$('#roof-detail').innerHTML='';$('#roof-chart').innerHTML='';return;}$('#roof-value').innerHTML=`${r.attainable.toFixed(2)} <small>TFLOP/s</small>`;$('#roof-bound').textContent=a<r.ridge?'Bandwidth-bound in this simplified model. More data reuse can raise the ceiling.':'Compute-bound in this simplified model. More intensity alone cannot raise the ceiling.';$('#roof-detail').innerHTML=`<div><span>Ridge point</span><strong>${r.ridge.toFixed(2)} FLOP/byte</strong></div><div><span>Memory ceiling at this intensity</span><strong>${r.memory.toFixed(2)} TFLOP/s</strong></div>`;const maxX=Math.max(r.ridge*2,a*1.2),sx=x=>50+x/maxX*650,sy=y=>220-y/p*170;$('#roof-chart').innerHTML=`<svg viewBox="0 0 740 280" role="img" aria-label="Linear roofline chart: bandwidth ceiling rises with arithmetic intensity until the compute ceiling is reached"><path d="M50 35V220H705" stroke="#9cac90" fill="none"/><path d="M50 ${sy(p)}H705" stroke="#d1dcc5" stroke-dasharray="4 4"/><path d="M50 220L${sx(r.ridge)} ${sy(p)}H705" stroke="#6c8e4b" fill="none" stroke-width="3"/><path d="M${sx(a)} 220V${sy(r.attainable)}" stroke="#d7663d" stroke-dasharray="4 4"/><circle cx="${sx(a)}" cy="${sy(r.attainable)}" r="6" fill="#d7663d"/><g font-family="monospace" font-size="11" fill="#718363"><text x="50" y="25">TFLOP/s · ${p} peak</text><text x="50" y="244">0</text><text x="${Math.max(60,Math.min(570,sx(r.ridge)-55))}" y="244">ridge ${r.ridge.toFixed(1)}</text><text x="420" y="269">Arithmetic intensity · FLOP/byte →</text></g></svg>`;}
function initTool(){if(activeTool==='memory')updateMemory();else if(activeTool==='roofline')updateRoofline();else updateArchitecture();}
const interviewQuestions=[
 ['GPU utilization is high, but inference is slow. What next?','Establish the request distribution, SLO, concurrency, input/output lengths, and time to first token versus time per output token. Utilization does not prove useful compute efficiency. Trace queueing, prefill, decode, transfers, and CPU gaps; inspect memory bandwidth and kernel throughput. Change one bottleneck at a time and compare latency percentiles and completed requests under the same workload.'],
 ['Why can a smaller batch be slower per example?','Small batches may offer too little parallel work and amortize launch overhead poorly. Larger batches can improve reuse and utilization, but increase activation memory and queueing delay. Benchmark the throughput/latency frontier at representative shapes; there is no universal best batch size.'],
 ['An LLM fits at startup, then runs out of memory. Why?','Loading mostly exposes weights and startup allocations. Requests add KV cache, activations, temporary workspace, and graph buffers; allocator fragmentation or competing processes can further reduce usable memory. Measure peak allocated and reserved memory under maximum expected context and concurrency, then enforce admission limits with headroom.'],
 ['How do you benchmark a CUDA operation correctly?','Warm up representative shapes, exclude compilation unless measuring cold start, use CUDA events on the relevant stream for GPU time, and synchronize before reading the result. Measure wall-clock time with explicit synchronization for end-to-end work. Report repetitions and distribution, hardware/software versions, precision, and whether transfers were included.'],
 ['When does kernel fusion help, and when can it hurt?','Fusion often saves kernel launches and intermediate device-memory traffic. Larger fused kernels can increase register pressure, reduce occupancy, inhibit better library kernels, or duplicate work. Validate outputs and compare both kernel-level metrics and end-to-end performance.'],
 ['What is the difference between allocated and reserved GPU memory?','Allocated memory refers to live tensor allocations tracked by the framework. Reserved memory includes allocator-managed segments, some currently free for reuse. Device tools also account for other consumers. Releasing cached blocks does not free live tensors, and routinely emptying the cache can slow allocation-heavy workloads.'],
 ['Why is a non-blocking copy not guaranteed to overlap compute?','The host call may return early without true device concurrency. Host memory type, copy engine capability, stream ordering, dependencies, and buffer lifetimes determine overlap. Use a timeline to demonstrate that independent transfers and kernels actually execute concurrently.'],
 ['How do you choose BF16, FP16, or quantized inference?','Match device and kernel support, accuracy requirements, and the actual bottleneck. BF16 offers a wide exponent range with less mantissa precision; FP16 has different numerical limits. Quantization reduces storage but adds metadata and sometimes dequantization overhead. Evaluate task quality, latency, throughput, and peak memory with the intended serving engine.'],
 ['Design a reliable one-GPU model service.','Define API shape and token limits, load the model before readiness, bound request queues and concurrency, and enforce timeouts and cancellation. Measure TTFT, output-token latency, request success, and memory. Add health checks, reproducible images, model versioning, controlled rollout, and a recovery plan. A single GPU is a failure domain; meaningful availability may require a replica elsewhere.'],
 ['When should you move beyond one GPU?','First determine whether capacity, compute, or service-level concurrency is the constraint. Compare independent replicas with model sharding. Explain communication cost and topology for tensor parallelism, pipeline bubbles for pipeline parallelism, and optimizer/state sharding for training. Include failure recovery, storage throughput, and network bottlenecks in the design.'],
 ['How do you compare GPU serving cost fairly?','Use cost per successful request or useful output token while meeting the same quality and latency SLO. Include idle capacity, rejected or failed work, batching efficiency, CPU and storage costs, and operating overhead. A higher hourly price can still provide lower cost per useful unit; list assumptions instead of relying on peak TFLOP/s.'],
 ['What evidence makes an optimization convincing?','A reproducible baseline, a specific hypothesis, a correctness and quality check, and repeated before/after measurements under the same workload. Include an annotated profile, limitations, regressions at other shapes, and an end-to-end effect. Report failed hypotheses as engineering evidence too.']
];
function career(){return `${intro('FROM UNDERSTANDING TO ENGINEERING','Turn knowledge into evidence.','AI infrastructure spans kernels, ML frameworks, serving, distributed systems, and reliable operations. Use this path to build transferable judgment, then specialize for the role you want.')}<div class="weekly-plan">${[['WEEKS 01—02','Learn the machine','Modules 01–07. Explain a warp, follow a tensor through memory, and build a reproducible CUDA/PyTorch environment.'],['WEEKS 03—04','Measure before tuning','Modules 08–12. Capture a timeline, build a roofline estimate, and fix one measured performance bottleneck.'],['WEEKS 05—06','Serve a workload','Modules 13–17. Measure prefill and decode, budget memory, and define observable service-level objectives.'],['WEEKS 07—08','Operate & explain','Modules 18–20. Exercise failure recovery, compare scaling options, and publish a reproducible engineering report.']].map(([w,h,p])=>`<div class="week"><span class="eyebrow">${w}</span><h3>${h}</h3><p>${p}</p></div>`).join('')}</div><p class="notice">Suggested pace: 5–8 hours per week including labs. Adjust to your background and hardware access. Completion is a learning milestone, not a certification or guarantee of job readiness.</p><div class="section-head"><div><span class="eyebrow">A PORTFOLIO WITH SUBSTANCE</span><h2>Three projects worth explaining.</h2></div></div><div class="project-grid">${[['01 / PERFORMANCE','The bottleneck notebook','Build a small, repeatable PyTorch benchmark and make one measured optimization.',['Record shapes, dtypes, versions, warmup, and timing method.','Capture before/after timelines and memory peaks.','Validate numerical correctness and document one failed hypothesis.']],['02 / SERVING','The one-GPU inference service','Serve a small model and test the latency/throughput tradeoff under realistic load.',['Measure TTFT, time per output token, p95 latency, and errors.','Bound concurrency and context length; monitor KV-cache demand.','Compare quality and performance across two supported precision choices.']],['03 / OPERATIONS','The reliability field report','Package a reproducible workload and document how to diagnose and recover failures.',['Create an observable container deployment and a runbook.','Exercise a safe process restart and an intentionally bounded OOM case.','Explain the next scaling constraint: device, CPU, storage, or network.']]].map(([tag,h,p,ls])=>`<div class="project"><span class="eyebrow">${tag}</span><h3>${h}</h3><p>${p}</p><ul>${ls.map(l=>`<li>${l}</li>`).join('')}</ul></div>`).join('')}</div><div class="section-head"><div><span class="eyebrow">INTERVIEW REASONING / 12 PROMPTS</span><h2>Explain the tradeoff, not just the term.</h2></div></div><div class="interview-list">${interviewQuestions.map(([q,a],i)=>`<details><summary><span class="question-index">${String(i+1).padStart(2,'0')}</span>${q}</summary><p>${a}</p></details>`).join('')}</div>`;}
const glossary=[['Warp','A CUDA scheduling group of 32 threads. Divergent execution can reduce useful parallel work.'],['SM','Streaming multiprocessor: a unit containing schedulers, execution resources, registers, and on-chip storage.'],['Occupancy','Active resident warps relative to a device-specific maximum. One factor in latency hiding, not a performance score.'],['Coalescing','Combining a warp’s memory requests into efficient transactions; the access pattern and alignment matter.'],['Arithmetic intensity','Work performed per byte transferred, measured at a specified memory level. Usually FLOP/byte.'],['Roofline','A performance upper-bound model combining compute throughput and memory bandwidth.'],['KV cache','Stored attention keys and values used to avoid recomputing past token states during autoregressive generation.'],['GQA','Grouped-query attention: multiple query heads share fewer key/value heads, reducing KV-cache size.'],['TTFT','Time to first token. State whether queueing, network transfer, and prompt processing are included.'],['TPOT / ITL','Time per output token or inter-token latency. Definitions and averaging differ; report the exact measurement.'],['MIG','Multi-Instance GPU partitions supported GPUs into hardware-isolated instances with assigned compute and memory resources.'],['MPS','Multi-Process Service coordinates CUDA work from multiple processes; isolation properties differ from MIG.'],['NCCL','NVIDIA Collective Communications Library for multi-GPU communication operations such as all-reduce.'],['SLO / goodput','A service-level objective defines acceptable behavior. Goodput counts useful completed work satisfying the chosen objective.'],['NUMA','Non-uniform memory access: CPU-to-memory and device locality affect host-side data movement.'],['FSDP / ZeRO','Families of distributed training approaches that shard model state; communication and peak-memory behavior depend on configuration.']];
function resources(){const unique=[...new Map(modules.flatMap(m=>m.sources).map(s=>[s.url,s])).values()];return `${intro('KEEP THE PRIMARY SOURCES CLOSE','Your reference shelf.','The guide explains mental models; primary documentation resolves version-specific details. Follow the references attached to each lesson and match them to your installed software and GPU generation.')}<p class="notice">Content assembled November 2026. External documentation changes over time; this is not a claim that every linked version was tested. GPU labs are instructional examples and have not been executed on your hardware.</p><div class="section-head"><div><span class="eyebrow">THE VOCABULARY OF THE STACK</span><h2>Sixteen terms to keep straight.</h2></div></div><dl class="glossary">${glossary.map(([t,d])=>`<div><dt>${t}</dt><dd>${d}</dd></div>`).join('')}</dl><div class="section-head"><div><span class="eyebrow">OFFICIAL DOCS & PRIMARY REFERENCES</span><h2>Read deeper.</h2></div><span class="eyebrow">${unique.length} REFERENCES</span></div><div class="resources-list">${unique.map(s=>`<a class="resource" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer"><span class="eyebrow">${esc(new URL(s.url).hostname)}</span><h3>${esc(s.label)}</h3><span>Open reference ↗</span></a>`).join('')}</div>`;}
function render(){const [rawPage,arg]=location.hash.slice(1).split('/');const page=rawPage||'overview';const names={overview:'Overview',curriculum:'Learning path',lesson:'Learning path',playground:'GPU playground',interview:'Career & interviews',resources:'Reference library'};let html;switch(page){case 'curriculum':html=curriculum(arg);break;case 'lesson':html=lesson(arg);break;case 'playground':html=playground();break;case 'interview':html=career();break;case 'resources':html=resources();break;default:html=overview();}$('#main').innerHTML=html;$('#breadcrumb-current').textContent=names[page]||'Overview';$$('[data-nav]').forEach(a=>{const selected=a.dataset.nav===(page==='lesson'?'curriculum':page);a.classList.toggle('active',selected);if(selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('.sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');document.title=`${page==='lesson'?(modules.find(m=>m.id===arg)?.title||'Lesson'):names[page]||'Overview'} — GPU Field Guide`;if(page==='playground')initTool();window.scrollTo(0,0);updateProgress();}
document.addEventListener('click',async e=>{
 const scroll=e.target.closest('[data-scroll]');if(scroll){e.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:'smooth'});if(scroll.dataset.scroll==='main')$('#main').focus({preventScroll:true});return;}
 const group=e.target.closest('[data-group]');if(group){activeGroup=group.dataset.group;$$('[data-group]').forEach(b=>b.classList.toggle('active',b===group));$('#module-list').innerHTML=moduleList();return;}
 const tool=e.target.closest('[data-tool]');if(tool){activeTool=tool.dataset.tool;$$('[data-tool]').forEach(b=>b.classList.toggle('active',b===tool));$('#tool-content').innerHTML=toolContent();initTool();return;}
 const part=e.target.closest('[data-part]');if(part){$$('[data-part]').forEach(b=>b.classList.toggle('active',b===part));updateArchitecture(part.dataset.part);return;}
 const answer=e.target.closest('[data-answer]');if(answer){const m=modules.find(m=>m.id===answer.dataset.lesson),correct=Number(answer.dataset.answer)===m.quiz.answer;$$('.choice').forEach(b=>{b.classList.remove('selected','correct');if(Number(b.dataset.answer)===m.quiz.answer)b.classList.add('correct');});if(!correct)answer.classList.add('selected');$('.quiz-result').textContent=`${correct?'Correct.':'Review the highlighted answer.'} ${m.quiz.explanation}`;return;}
 const complete=e.target.closest('[data-complete]');if(complete){const id=complete.dataset.complete;if(completed.has(id))completed.delete(id);else completed.add(id);saveProgress();complete.textContent=completed.has(id)?'✓ Completed · mark unread':'Mark module complete ✓';complete.classList.toggle('light',completed.has(id));toast(completed.has(id)?'Module complete. Keep building your understanding.':'Module marked unread.');return;}
 const copy=e.target.closest('[data-copy]');if(copy){try{await navigator.clipboard.writeText(modules.find(m=>m.id===copy.dataset.copy).lab.code);toast('Lab code copied.');}catch(_){toast('Copy unavailable. Select the code and copy it manually.');}return;}
 const result=e.target.closest('#search-results a');if(result)$('#search-dialog').close();
});
document.addEventListener('input',e=>{if(e.target.id==='curriculum-search'){filterText=e.target.value;$('#module-list').innerHTML=moduleList();}if(e.target.closest('#tool-content')){if(activeTool==='memory')updateMemory();else if(activeTool==='roofline')updateRoofline();}});
function search(){const q=$('#global-search').value.trim(),results=modules.filter(m=>matches(m,q));$('#search-results').innerHTML=results.length?results.map(m=>`<a href="#lesson/${m.id}"><h3>${esc(m.title)}</h3><p>${esc(m.group)} · ${esc(m.tags.join(' / '))}</p></a>`).join(''):'<p class="empty">No matching concepts. Try a broader keyword.</p>';}
function openSearch(){$('#search-dialog').showModal();$('#global-search').value='';search();$('#global-search').focus();}
$('#search-open').addEventListener('click',openSearch);$('#search-close').addEventListener('click',()=>$('#search-dialog').close());$('#global-search').addEventListener('input',search);
document.addEventListener('keydown',e=>{if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#search-dialog').open){e.preventDefault();openSearch();}if(e.key==='Escape'){$('.sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}});
$('#menu-toggle').addEventListener('click',()=>{const open=$('.sidebar').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));});
$('#reset-progress').addEventListener('click',()=>{if(confirm('Reset all completed modules in this browser?')){completed.clear();saveProgress();render();toast('Progress reset.');}});
window.addEventListener('hashchange',()=>{render();$('#main').focus({preventScroll:true});});render();
